def format_title(txt):
    if not txt:
        return ""
    words = txt.strip().split()
    return " ".join(w.capitalize() for w in words)

target_dir = r"C:\Users\julio\dev\sitio-web-csd\src\admisiones"
os.makedirs(target_dir, exist_ok=True)

# Build SHA-256 hashed database for security and privacy
hashed_db = {}
for doc, est in raw_data.items():
    doc_clean = re.sub(r'[^0-9]', '', doc)
    h = hashlib.sha256(doc_clean.encode('utf-8')).hexdigest()
    
    # Clean fields
    nombre_formateado = format_title(est["nombre"])
    acudiente_formateado = format_title(est["acudiente"])
    
    hashed_db[h] = {
        "doc": doc_clean,
        "nombre": nombre_formateado,
        "grado_2027": est["grado_2027"].strip(),
        "salon": est["salon"].strip(),
        "acudiente": acudiente_formateado,
        "doc_acudiente": est.get("doc_acudiente", "").strip(),
        "celular": est.get("celular", "").strip(),
        "estado_pago": est.get("estado_pago", "PENDIENTE").strip()
    }

output_path = os.path.join(target_dir, "admitidos_hash.json")
with open(output_path, "w", encoding="utf-8") as f:
    json.dump(hashed_db, f, ensure_ascii=False, indent=2)

print(f"SUCCESS: Generated {len(hashed_db)} hashed student records in {output_path}")
